fn add_v51_local_schema_extensions(
    marker: i64,
    tables: &mut Vec<&'static str>,
    indexes: &mut Vec<&'static str>,
    triggers: &mut Vec<(&'static str, &'static str)>,
) {
    if marker >= 51 {

        tables.push("taskrun_local_command_attempts");
        indexes.push("taskrun_local_command_writer_active");
        triggers.extend([
            ("taskrun_local_command_identity_immutable", "CREATE TRIGGER taskrun_local_command_identity_immutable BEFORE UPDATE ON taskrun_local_command_attempts WHEN NEW.taskrun_id!=OLD.taskrun_id OR NEW.conversation_id!=OLD.conversation_id OR NEW.workspace_id!=OLD.workspace_id OR NEW.command_digest!=OLD.command_digest OR (OLD.attempt_id IS NOT NULL AND NEW.attempt_id IS NOT OLD.attempt_id) OR (OLD.node_id IS NOT NULL AND NEW.node_id IS NOT OLD.node_id) OR (OLD.node_epoch IS NOT NULL AND NEW.node_epoch IS NOT OLD.node_epoch) OR (OLD.fence IS NOT NULL AND NEW.fence IS NOT OLD.fence) OR (OLD.executable_digest IS NOT NULL AND NEW.executable_digest IS NOT OLD.executable_digest) OR (OLD.workspace_version IS NOT NULL AND NEW.workspace_version IS NOT OLD.workspace_version) OR (OLD.admitted_root_version IS NOT NULL AND NEW.admitted_root_version IS NOT OLD.admitted_root_version) OR (OLD.admitted_root_identity IS NOT NULL AND NEW.admitted_root_identity IS NOT OLD.admitted_root_identity) OR (OLD.trust_epoch IS NOT NULL AND NEW.trust_epoch IS NOT OLD.trust_epoch) OR (OLD.trust_revision IS NOT NULL AND NEW.trust_revision IS NOT OLD.trust_revision) OR (OLD.source_policy_version IS NOT NULL AND NEW.source_policy_version IS NOT OLD.source_policy_version) OR (OLD.command_policy_version IS NOT NULL AND NEW.command_policy_version IS NOT OLD.command_policy_version) OR (OLD.approval_id IS NOT NULL AND NEW.approval_id IS NOT OLD.approval_id) OR (OLD.managed_area_identity IS NOT NULL AND NEW.managed_area_identity IS NOT OLD.managed_area_identity) BEGIN SELECT RAISE(ABORT,'TaskRun local command identity is immutable'); END"),
            ("taskrun_local_command_state_transition", "CREATE TRIGGER taskrun_local_command_state_transition BEFORE UPDATE OF state ON taskrun_local_command_attempts WHEN NOT ((OLD.state='preflight' AND NEW.state IN ('approval_pending','approved','denied','no_effect_terminal','outcome_unknown')) OR (OLD.state='approval_pending' AND NEW.state IN ('approved','denied','no_effect_terminal','outcome_unknown')) OR (OLD.state='approved' AND NEW.state IN ('launch_intent','denied','no_effect_terminal','outcome_unknown')) OR (OLD.state='launch_intent' AND NEW.state IN ('release_reserved','cancel_requested','stop_unconfirmed','outcome_unknown')) OR (OLD.state='release_reserved' AND NEW.state IN ('running','cancel_requested','stop_unconfirmed','outcome_unknown')) OR (OLD.state='running' AND NEW.state IN ('completed','cancel_requested','stop_unconfirmed','outcome_unknown')) OR (OLD.state='cancel_requested' AND NEW.state IN ('cancelled','stop_unconfirmed','outcome_unknown')) OR (OLD.state='stop_unconfirmed' AND NEW.state IN ('cancelled','outcome_unknown')) OR (OLD.state='outcome_unknown' AND NEW.state IN ('cancelled','completed','stop_unconfirmed'))) BEGIN SELECT RAISE(ABORT,'TaskRun local command state transition is invalid'); END"),
            ("taskrun_local_command_no_delete", "CREATE TRIGGER taskrun_local_command_no_delete BEFORE DELETE ON taskrun_local_command_attempts BEGIN SELECT RAISE(ABORT,'TaskRun local command record is retained'); END"),
            ("schema_v12_fence_taskrun_local_command_attempts_insert", "CREATE TRIGGER \"schema_v12_fence_taskrun_local_command_attempts_insert\" AFTER INSERT ON \"taskrun_local_command_attempts\" BEGIN INSERT INTO schema_upgrade_write_latch (id, closed) VALUES (1, 1) ON CONFLICT(id) DO NOTHING; END"),
            ("schema_v12_fence_taskrun_local_command_attempts_update", "CREATE TRIGGER \"schema_v12_fence_taskrun_local_command_attempts_update\" AFTER UPDATE ON \"taskrun_local_command_attempts\" BEGIN INSERT INTO schema_upgrade_write_latch (id, closed) VALUES (1, 1) ON CONFLICT(id) DO NOTHING; END"),
            ("schema_v12_fence_taskrun_local_command_attempts_delete", "CREATE TRIGGER \"schema_v12_fence_taskrun_local_command_attempts_delete\" AFTER DELETE ON \"taskrun_local_command_attempts\" BEGIN INSERT INTO schema_upgrade_write_latch (id, closed) VALUES (1, 1) ON CONFLICT(id) DO NOTHING; END"),
        ]);
    }
}
